presets.wrong_order:
import numpy as np


def dead_reckon(T_world_start, steps):
    # The step goes on the left: S @ T. The end of the lap still looks right; the middle does not.
    poses = [np.asarray(T_world_start, dtype=float)]
    for step in steps:
        poses.append(step @ poses[-1])
    return np.stack(poses)

presets.direction_with_w1:
import numpy as np


def transform_points(T, p):
    return np.asarray(p, dtype=float) @ T[:3, :3].T + T[:3, 3]  # w = 1: turns AND shifts


def ray_to_ground(T_ego_cam, ray_cam):
    lens = T_ego_cam[:3, 3]
    r = transform_points(T_ego_cam, ray_cam)  # a ray is a direction: it must only turn (w = 0)
    if r[2] >= 0:
        return np.full(3, np.nan)
    return lens + (-lens[2] / r[2]) * r
